import Foundation
import XCTest
@testable import ColorComposerCore

/// Solver parity against the committed `color_matching` corpus (issue #39).
///
/// The corpus is generated by the Elixir `WeightedSquaredError` solver and
/// committed at `ColorComposerCore/ParityCorpus/solver_parity_corpus.json`
/// (viamin/color_matching#111; schema and refresh steps in
/// docs/solver-parity-corpus.md). Every case must select exactly the expected
/// palette color: ties resolve to the earliest entry in palette order on both
/// sides, a candidate missing a measurement for a weight > 0 channel is
/// excluded rather than treated as zero brightness, and channels with weight
/// zero (or absent) never influence the outcome.
///
/// Deliberately over the ~100-line guideline: the loader, corpus DTOs, and
/// the three parity assertions (scorer selection, solver fast path, corpus
/// structure) share one corpus-naming contract that splitting would only
/// spread around.
final class SolverParityCorpusTests: XCTestCase {
    private let scorer = WeightedSquaredErrorScorer()

    // MARK: - Parity

    func testCorpusIsCommittedAndStructurallyValid() {
        guard let corpus = loadCorpus() else { return }

        XCTAssertEqual(corpus.version, 1, "corpus version must be 1; refresh per docs/solver-parity-corpus.md")

        let ids = corpus.cases.map(\.id)
        XCTAssertEqual(Set(ids).count, ids.count, "corpus case ids must be unique")
        XCTAssertFalse(corpus.cases.isEmpty, "corpus must contain at least one case")

        for parityCase in corpus.cases {
            _ = build(parityCase)
        }

        XCTAssertFalse(
            corpus.cases.filter { $0.expected.tie == true }.isEmpty,
            "corpus must include at least one tie case (earliest-entry tie-breaking is part of the contract)"
        )
        XCTAssertFalse(
            corpus.cases.filter { !($0.expected.excludedColorIds ?? []).isEmpty }.isEmpty,
            "corpus must include at least one case with excluded candidates (missing-measurement policy)"
        )
        XCTAssertFalse(
            corpus.cases.filter { $0.weights.values.contains(0) }.isEmpty,
            "corpus must include at least one case with an explicit zero channel weight"
        )
    }

    func testScorerSelectionsMatchCorpusExpectationsExactly() {
        guard let corpus = loadCorpus() else { return }

        for parityCase in corpus.cases {
            guard let built = build(parityCase) else { continue }
            assertSelectionParity(parityCase, built: built)
        }
    }

    func testSolverFastPathSelectsTheSameColorsAsTheCorpus() throws {
        guard let corpus = loadCorpus() else { return }

        for parityCase in corpus.cases {
            guard let built = build(parityCase) else { continue }

            var grids: [LightingCondition: BrightnessGrid] = [:]
            for (condition, _) in built.weights.activeEntries {
                grids[condition] = BrightnessGrid(
                    width: 1,
                    height: 1,
                    fill: built.target.value(for: condition) ?? 0
                )
            }

            let result: CompositionResult
            do {
                result = try CompositionSolver().solve(
                    palette: built.palette,
                    sourceGrids: grids,
                    weights: built.weights
                )
            } catch {
                XCTFail("case \(parityCase.id): solver threw \(error)")
                continue
            }

            let selectedIndex = result.colorIndex(x: 0, y: 0)
            if let expectedId = parityCase.expected.selectedColorId {
                let index = try XCTUnwrap(
                    selectedIndex,
                    "case \(parityCase.id): solver matched no color, expected \(expectedId)"
                )
                XCTAssertEqual(
                    built.palette[index].id,
                    expectedId,
                    "case \(parityCase.id): solver fast path disagrees with the corpus"
                )
            } else {
                XCTAssertNil(
                    selectedIndex,
                    "case \(parityCase.id): expected no eligible candidate, solver matched a color"
                )
            }
        }
    }

    // MARK: - Selection parity

    private struct Selection {
        let index: Int
        let colorId: Int
        let score: Double
    }

    private func selectEarliestWinner(
        palette: [PaletteColor],
        target: TargetResponseVector,
        weights: ChannelWeights
    ) -> Selection? {
        var best: Selection?
        for (index, color) in palette.enumerated() {
            guard case .score(let score) = scorer.score(candidate: color, target: target, weights: weights) else {
                continue
            }
            if score < (best?.score ?? .infinity) {
                best = Selection(index: index, colorId: color.id, score: score)
            }
        }
        return best
    }

    private func assertSelectionParity(
        _ parityCase: SolverParityCorpus.ParityCase,
        built: BuiltCase
    ) {
        let caseId = parityCase.id
        let expected = parityCase.expected
        let winner = selectEarliestWinner(palette: built.palette, target: built.target, weights: built.weights)

        guard let expectedId = expected.selectedColorId else {
            XCTAssertNil(winner, "case \(caseId): expected every candidate to be excluded")
            return
        }

        guard let winner else {
            XCTFail("case \(caseId): expected color \(expectedId) to be selected, but no candidate was eligible")
            return
        }

        XCTAssertEqual(winner.colorId, expectedId, "case \(caseId): selection mismatch")

        if let expectedScore = expected.score {
            XCTAssertEqual(
                winner.score,
                expectedScore,
                accuracy: 1e-9,
                "case \(caseId): score mismatch for color \(expectedId)"
            )
        }

        if expected.tie == true {
            assertTieParity(parityCase, built: built, winner: winner, expectedId: expectedId)
        } else if expected.tie == false {
            assertNoHiddenTies(parityCase, built: built, winner: winner)
        }

        for excludedId in expected.excludedColorIds ?? [] {
            guard let color = built.palette.first(where: { $0.id == excludedId }) else {
                XCTFail("case \(caseId): excluded_color_ids references unknown palette entry \(excludedId)")
                continue
            }
            XCTAssertEqual(
                scorer.score(candidate: color, target: built.target, weights: built.weights),
                .excluded,
                "case \(caseId): color \(excludedId) must be excluded for a missing required measurement"
            )
        }
    }

    private func assertTieParity(
        _ parityCase: SolverParityCorpus.ParityCase,
        built: BuiltCase,
        winner: Selection,
        expectedId: Int
    ) {
        let caseId = parityCase.id
        let tiedIds = parityCase.expected.tiedColorIds ?? []

        XCTAssertTrue(
            tiedIds.contains(expectedId),
            "case \(caseId): tied_color_ids must include the selected color \(expectedId)"
        )

        let tiedIndexes = tiedIds.compactMap { id in built.palette.firstIndex { $0.id == id } }
        XCTAssertEqual(
            tiedIndexes.count,
            tiedIds.count,
            "case \(caseId): tied_color_ids reference unknown palette entries"
        )
        if let earliestTied = tiedIndexes.min() {
            XCTAssertEqual(
                winner.index,
                earliestTied,
                "case \(caseId): tie must resolve to the earliest palette entry among \(tiedIds)"
            )
        }

        for id in tiedIds {
            guard let color = built.palette.first(where: { $0.id == id }),
                  case .score(let score) = scorer.score(candidate: color, target: built.target, weights: built.weights)
            else {
                XCTFail("case \(caseId): tied color \(id) must be eligible")
                continue
            }
            XCTAssertEqual(
                score,
                winner.score,
                accuracy: 1e-12,
                "case \(caseId): tied color \(id) must share the winning score"
            )
        }
    }

    private func assertNoHiddenTies(
        _ parityCase: SolverParityCorpus.ParityCase,
        built: BuiltCase,
        winner: Selection
    ) {
        for (index, color) in built.palette.enumerated() where index != winner.index {
            guard case .score(let score) = scorer.score(candidate: color, target: built.target, weights: built.weights) else {
                continue
            }
            XCTAssertGreaterThan(
                score,
                winner.score + 1e-12,
                "case \(parityCase.id): color \(color.id) ties the winner but the case is not flagged as a tie"
            )
        }
    }

    // MARK: - Corpus → domain conversion

    private struct BuiltCase {
        let palette: [PaletteColor]
        let target: TargetResponseVector
        let weights: ChannelWeights
    }

    /// Converts one corpus case into solver-domain values, validating the
    /// corpus contract: known light-source keys only, parseable hex, unique
    /// palette ids, at least one positive weight, and a target value for
    /// every weight > 0 condition.
    private func build(_ parityCase: SolverParityCorpus.ParityCase) -> BuiltCase? {
        let caseId = parityCase.id

        guard let weightMap = conditions(parityCase.weights, caseId: caseId, field: "weights"),
              let targetMap = conditions(parityCase.target, caseId: caseId, field: "target") else { return nil }

        let weights = ChannelWeights(
            white: weightMap[.white] ?? 0,
            red: weightMap[.red] ?? 0,
            green: weightMap[.green] ?? 0,
            blue: weightMap[.blue] ?? 0,
            lps: weightMap[.lps] ?? 0
        )
        guard !weights.activeEntries.isEmpty else {
            XCTFail("case \(caseId): at least one channel weight must be greater than zero")
            return nil
        }
        for (condition, _) in weights.activeEntries {
            guard targetMap[condition] != nil else {
                XCTFail("case \(caseId): target must measure the required condition \(condition.rawValue)")
                return nil
            }
        }

        guard !parityCase.palette.isEmpty else {
            XCTFail("case \(caseId): palette must not be empty")
            return nil
        }
        var palette: [PaletteColor] = []
        var seenIds = Set<Int>()
        for entry in parityCase.palette {
            guard let rgb = RGBColor(hex: entry.hex) else {
                XCTFail("case \(caseId): palette entry \(entry.id) has unparseable hex \"\(entry.hex)\"")
                return nil
            }
            guard seenIds.insert(entry.id).inserted else {
                XCTFail("case \(caseId): duplicate palette id \(entry.id)")
                return nil
            }
            var responses: [LightingCondition: IlluminationResponse] = [:]
            for (key, measured) in entry.responses {
                guard let condition = LightingCondition(rawValue: key) else {
                    XCTFail("case \(caseId): unknown light source \"\(key)\" in responses of color \(entry.id)")
                    return nil
                }
                responses[condition] = IlluminationResponse(brightness: measured.brightness)
            }
            palette.append(PaletteColor(id: entry.id, hex: entry.hex, rgb: rgb, responses: responses))
        }

        return BuiltCase(palette: palette, target: TargetResponseVector(targetMap), weights: weights)
    }

    private func conditions(
        _ values: [String: Double],
        caseId: String,
        field: String
    ) -> [LightingCondition: Double]? {
        var mapped: [LightingCondition: Double] = [:]
        for (key, value) in values {
            guard let condition = LightingCondition(rawValue: key) else {
                XCTFail("case \(caseId): unknown light source \"\(key)\" in \(field)")
                return nil
            }
            mapped[condition] = value
        }
        return mapped
    }

    // MARK: - Loading

    private func loadCorpus() -> SolverParityCorpus? {
        do {
            return try SolverParityCorpusLoader.load()
        } catch {
            XCTFail("Solver parity corpus could not be loaded: \(error.localizedDescription)")
            return nil
        }
    }
}

// MARK: - Corpus wire format

private struct SolverParityCorpus: Codable {
    struct ParityCase: Codable {
        struct PaletteEntry: Codable {
            struct Measured: Codable {
                let brightness: Double
            }

            let id: Int
            let hex: String
            let responses: [String: Measured]
        }

        struct Expected: Codable {
            let selectedColorId: Int?
            let score: Double?
            let tie: Bool?
            let tiedColorIds: [Int]?
            let excludedColorIds: [Int]?

            enum CodingKeys: String, CodingKey {
                case selectedColorId = "selected_color_id"
                case score
                case tie
                case tiedColorIds = "tied_color_ids"
                case excludedColorIds = "excluded_color_ids"
            }
        }

        let id: String
        let description: String?
        let weights: [String: Double]
        let palette: [PaletteEntry]
        let target: [String: Double]
        let expected: Expected
    }

    let version: Int
    let cases: [ParityCase]
}

private enum SolverParityCorpusError: LocalizedError {
    case missing(searchedPaths: [String])
    case malformed(path: String, underlying: Error)

    var errorDescription: String? {
        switch self {
        case .missing(let searchedPaths):
            return "commit the corpus (viamin/color_matching#111) at \(searchedPaths.joined(separator: " or ")), " +
                "or point COLOR_MATCHING_PARITY_CORPUS at a generated copy — " +
                "see docs/solver-parity-corpus.md"
        case .malformed(let path, let underlying):
            return "corpus at \(path) does not match the documented schema: \(underlying)"
        }
    }
}

private enum SolverParityCorpusLoader {
    static let environmentOverride = "COLOR_MATCHING_PARITY_CORPUS"
    static let packageRelativeSearchPaths = [
        "ParityCorpus/solver_parity_corpus.json",
        "Tests/ColorComposerCoreTests/Fixtures/solver_parity_corpus.json"
    ]

    static func load() throws -> SolverParityCorpus {
        if let override = ProcessInfo.processInfo.environment[environmentOverride],
           !override.isEmpty {
            return try decode(URL(fileURLWithPath: override))
        }

        let packageRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()  // ColorComposerCoreTests
            .deletingLastPathComponent()  // Tests
            .deletingLastPathComponent()  // ColorComposerCore package root
        for relativePath in packageRelativeSearchPaths {
            let url = packageRoot.appendingPathComponent(relativePath)
            if FileManager.default.fileExists(atPath: url.path) {
                return try decode(url)
            }
        }
        throw SolverParityCorpusError.missing(
            searchedPaths: packageRelativeSearchPaths.map { "ColorComposerCore/\($0)" }
        )
    }

    private static func decode(_ url: URL) throws -> SolverParityCorpus {
        do {
            return try JSONDecoder().decode(SolverParityCorpus.self, from: try Data(contentsOf: url))
        } catch {
            throw SolverParityCorpusError.malformed(path: url.path, underlying: error)
        }
    }
}
